/**
 * Check if a date string is valid and in YYYY-MM-DD format.
 * All dates are interpreted as UTC.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (typeof text !== 'string') return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const date = new Date(text + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(text);
}

/**
 * Add n days to a date string. Returns a new date in YYYY-MM-DD format.
 * All arithmetic is done in UTC.
 * @param {string} date - date in YYYY-MM-DD format
 * @param {number} n - number of days to add
 * @returns {string} - new date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().split('T')[0];
}

/**
 * Calculate the number of whole days between two dates (b - a).
 * All arithmetic is done in UTC.
 * @param {string} a - first date in YYYY-MM-DD format
 * @param {string} b - second date in YYYY-MM-DD format
 * @returns {number} - number of whole days (b minus a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const msPerDay = 24 * 60 * 60 * 1000;
  return Math.round((dateB - dateA) / msPerDay);
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number from 0 to 100.',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  NOT_DRAFT: 'Only draft invoices can be modified.',
  NOT_ISSUED: 'Invoice must be issued before recording payments.',
  NO_LINES: 'An invoice must have at least one line item.',
  OVERPAYMENT: 'Payment exceeds the amount owed.',
  QTY_INVALID: 'Line item quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

