test('invoiceTotals: VAT on line without discount', () => {
  // DEV-HOUR has 21% VAT, unit price 9500
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 0 }],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Line total: 1 * 9500 = 9500
  // VAT: 9500 * 21 / 100 = 1995
  assert.equal(totals.subtotal, 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1995);
  assert.equal(totals.total, 11495);
});

test('invoiceTotals: VAT on line with discount', () => {
  // DEV-HOUR has 21% VAT, unit price 9500
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Line total: 10 * 9500 = 95000
  // Discount: 95000 * 10 / 100 = 9500
  // Discounted amount: 95000 - 9500 = 85500
  // VAT: 85500 * 21 / 100 = 17955
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

