test('invoiceTotals: VAT with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Dev: 5 * 9500 = 47500, discount 10% = 4750, discounted = 42750, VAT 21% = 8977.5 -> 8978
  // Des: 3 * 8500 = 25500, discount 0% = 0, discounted = 25500, VAT 21% = 5355
  // Workshop: 60000, discount 0% = 0, discounted = 60000, VAT 0% = 0
  assert.equal(totals.subtotal, 47500 + 25500 + 60000);
  assert.equal(totals.discount, 4750);
  const devVat = Math.round(42750 * 21 / 100);
  const desVat = Math.round(25500 * 21 / 100);
  assert.equal(totals.vat, devVat + desVat);
  assert.equal(totals.total, 47500 + 25500 + 60000 - 4750 + devVat + desVat);
});

